package com.bank.patterns;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.*;

public class PatternsDemo {
    private static final Logger log = Logger.getLogger(PatternsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));

        // CREATIONAL: factory decides the concrete settlement object
        SettlementStrategy strategy = SettlementFactory.create(TradeType.EQUITY);

        // STRUCTURAL: adapter exposes old ledger as the clean LedgerPort
        LedgerPort ledger = new LegacyLedgerAdapter(new LegacyLedger());

        // BEHAVIORAL: publisher notifies all listeners after settlement
        SettlementPublisher publisher = new SettlementPublisher();
        publisher.subscribe(evt -> log.info(() -> "AUDIT  : " + evt));
        publisher.subscribe(evt -> log.info(() -> "SMS    : Dear Rajesh, " + evt));

        BigDecimal amount = new BigDecimal("50000");
        log.info(() -> "Starting settlement of Rs." + amount + " for " + rajesh.getAccountId());
        strategy.settle(rajesh, amount, ledger);
        publisher.publish("SETTLED EQUITY Rs." + amount + " acct=" + rajesh.getAccountId());
        log.info(() -> "New balance: Rs." + rajesh.getBalance());
    }
}

// ─── Would be model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amt);
    }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
}

// ─── Would be model/TradeType.java ───
enum TradeType { EQUITY, FX, DERIVATIVE }

// ─── CREATIONAL: product interface ───
interface SettlementStrategy {
    void settle(Account account, BigDecimal amount, LedgerPort ledger);
}

// ─── CREATIONAL: concrete product ───
class EquitySettlement implements SettlementStrategy {
    public void settle(Account account, BigDecimal amount, LedgerPort ledger) {
        account.debit(amount);
        ledger.post(account.getAccountId(), amount);
    }
}

// ─── CREATIONAL: factory hides the 'new' ───
class SettlementFactory {
    static SettlementStrategy create(TradeType type) {
        return switch (type) {
            case EQUITY -> new EquitySettlement();
            default -> throw new IllegalArgumentException("No handler for " + type);
        };
    }
}

// ─── STRUCTURAL: clean target interface ───
interface LedgerPort { void post(String accountId, BigDecimal amount); }

// ─── STRUCTURAL: the old incompatible system ───
class LegacyLedger {
    void writeEntry(String acct, double amt) { /* old API, double + odd name */ }
}

// ─── STRUCTURAL: adapter bridges old to new ───
class LegacyLedgerAdapter implements LedgerPort {
    private final LegacyLedger legacy;
    LegacyLedgerAdapter(LegacyLedger legacy) { this.legacy = legacy; }
    public void post(String accountId, BigDecimal amount) {
        legacy.writeEntry(accountId, amount.doubleValue());
    }
}

// ─── BEHAVIORAL: observer contract ───
interface SettlementListener { void onSettled(String event); }

// ─── BEHAVIORAL: subject/publisher ───
class SettlementPublisher {
    private final List<SettlementListener> listeners = new ArrayList<>();
    void subscribe(SettlementListener l) { listeners.add(l); }
    void publish(String event) { listeners.forEach(l -> l.onSettled(event)); }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
